from pathlib import Path
import json,hashlib,os,shutil,datetime,stat
R=Path('/Users/chasen/.codex/worktrees/g6-p0-parser-prep-master/ontology-platform');E=R/'docs/evidence/G6-P0-PARSER-PREP-001'
names=['g6_setup.py','g6_contract_fix.py','g6_platform_tests.py','g6_platform_impl.py','g6_metadata.py','g6_metadata_finish.py','g6_expand_metadata.py','g6_fix_platform.py','g6_docs.py','g6_weight_metadata.py','g6_audit_files.py','g6_supply_report.py','g6_preflight_fix.py','g6_after.py','g6_readme.py']
collection=[]
for name in ['g6_metadata.py','g6_metadata_finish.py','g6_expand_metadata.py','g6_weight_metadata.py']:
 p=Path('/private/tmp')/name;raw=p.read_bytes();collection.append({'name':name,'sha256':hashlib.sha256(raw).hexdigest(),'utf8Text':raw.decode()})
(E/'metadata-acquisition.source.json').write_text(json.dumps({'kind':'ACTUAL_TASK_SCOPED_METADATA_COLLECTION_SOURCE_NOT_INSTALLER','scripts':collection},ensure_ascii=False,indent=2)+'\n')
rows=[]
for name in names:
 p=Path('/private/tmp')/name
 if not p.exists():rows.append({'path':str(p),'status':'NOT_PRESENT_NO_ACTION'});continue
 st=p.lstat()
 if not stat.S_ISREG(st.st_mode) or st.st_uid!=os.getuid():raise ValueError('UNSAFE_CANDIDATE')
 raw=p.read_bytes();h=hashlib.sha256(raw).hexdigest()
 if p.lstat()!=st or hashlib.sha256(p.read_bytes()).hexdigest()!=h:raise ValueError('CANDIDATE_CHANGED')
 p.unlink();rows.append({'path':str(p),'beforeFiles':1,'beforeBytes':len(raw),'sha256':h,'command':'Path.unlink exact verified task file','exitCode':0,'afterExists':p.exists(),'status':'REMOVED'})
p=Path('/private/tmp/G6-P0-PARSER-PREP-001-hd_ssfo_')
expected={x['path']:x for x in json.loads((E/'input/input-integrity.json').read_text())['members']}
files=[x for x in p.rglob('*') if x.is_file()]
if any(x.is_symlink() for x in p.rglob('*')) or p.is_symlink():raise ValueError('SYMLINK_CANDIDATE')
if set(str(x.relative_to(p)) for x in files)!=set(expected)|{'input-integrity.json'}:raise ValueError('UNKNOWN_EXTRA_FILE')
for rel,row in expected.items():
 raw=(p/rel).read_bytes()
 if len(raw)!=row['size'] or hashlib.sha256(raw).hexdigest()!=row['sha256']:raise ValueError('INPUT_CHANGED')
size=sum(x.stat().st_size for x in files);count=len(files)
shutil.rmtree(p)
rows.append({'path':str(p),'beforeFiles':count,'beforeBytes':size,'command':'shutil.rmtree exact task extraction after member hash and symlink recheck','exitCode':0,'afterExists':p.exists(),'status':'REMOVED','recovery':'Original user ZIP retained; 24 exact archived members validated by preflight'})
(E/'resources-cleanup.json').write_text(json.dumps({'taskId':'G6-P0-PARSER-PREP-001','runId':'prep-20261031','utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'Exact task temporary scripts/extraction only; no Docker/git/worktree/global cleanup','rows':rows,'logicalBytesRemoved':sum(x.get('beforeBytes',0) for x in rows),'filesystemPhysicalReclaimed':'NOT_VERIFIED','dockerDeleted':0},ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'objectsRemoved':sum(x['status']=='REMOVED' for x in rows),'filesRemoved':sum(x.get('beforeFiles',0) for x in rows),'logicalBytesRemoved':sum(x.get('beforeBytes',0) for x in rows)}))
